package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Split the second public operand into place values; learners enter every subtotal. */
public final class LargeMentalDecomposition {
 private LargeMentalDecomposition(){}
 public static final String ADD="largeMentalDecompositionAdd",SUB="largeMentalDecompositionSub";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(ADD,"큰 수를 나눠 더하기",5,1,1,"","largeMental",999999,MentalPlaceCalculations.ADD,"둘째 수를 자리값으로 나눠 차례로 더한다."),new Catalog.Skill(SUB,"큰 수를 나눠 빼기",5,1,1,"","largeMental",999999,MentalPlaceCalculations.SUB,"둘째 수를 자리값으로 나눠 차례로 뺀다."));
 private static final String[] PLACES={"일","십","백","천","만","십만","백만"};
 public static boolean supports(String id){return ADD.equals(id)||SUB.equals(id);}
 static Question make(String id,int a,int b){if(!supports(id)||a<0||a>1000000||b<0||b>1000000||SUB.equals(id)&&a<b)throw new IllegalArgumentException("large mental domain");Question q=new Question(id,a+(ADD.equals(id)?" + ":" - ")+b,"",Integer.toString(ADD.equals(id)?a+b:a-b));q.kind="largeMental";q.labels=new String[]{"답"};q.stepSupport=false;attach(q);return q;}
 public static int[] read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(0|[1-9][0-9]{0,6}) ([+−-]) (0|[1-9][0-9]{0,6})").matcher(q.prompt);if(!m.matches()||ADD.equals(q.skillId)!=m.group(2).equals("+"))return null;int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(3));if(a>1000000||b>1000000||SUB.equals(q.skillId)&&a<b)return null;return new int[]{a,b,ADD.equals(q.skillId)?a+b:a-b};}
 static long count(String id,int maximum){long size=maximum-999L;if(size<1||maximum>999999)throw new IllegalArgumentException("large mental maximum");return ADD.equals(id)?size*size:size*(size+1)/2;}
 static Question indexed(String id,int maximum,long index){long size=maximum-999L,total=count(id,maximum);if(index<0||index>=total)throw new IllegalArgumentException("large mental index");int a,b;if(ADD.equals(id)){a=1000+(int)(index/size);b=1000+(int)(index%size);}else{long low=0,high=size-1;while(low<high){long mid=(low+high+1)/2;if(mid*(mid+1)/2<=index)low=mid;else high=mid-1;}a=1000+(int)low;b=1000+(int)(index-low*(low+1)/2);}return make(id,a,b);}
 // Direct bounded indexing preserves every permitted pair, including zero and the million endpoint.
 static long prefix(int rows,int min,int max,int cap){long n=Math.min(rows,Math.max(0L,Math.min(max,cap-min)-min+1L)),full=Math.min(n,Math.max(0L,(long)cap-max-min+1)),partial=n-full;return full*(max-min+1L)+partial*(cap-2L*min-full+1)-partial*(partial-1)/2;}
 static long boundedCount(String id,int min,int max,int cap){if(!supports(id)||min<0||max<min||max>1000000||cap<0||cap>2000000)throw new IllegalArgumentException("mental range");long size=max-min+1L;return ADD.equals(id)?prefix((int)size,min,max,cap):size*(size+1)/2;}
 static Question bounded(String id,int min,int max,int cap,long index){long total=boundedCount(id,min,max,cap);if(index<0||index>=total)throw new IllegalArgumentException("mental index");int low=0,high=max-min;while(low<high){int mid=(low+high+1)/2;long start=ADD.equals(id)?prefix(mid,min,max,cap):(long)mid*(mid+1)/2;if(start<=index)low=mid;else high=mid-1;}long start=ADD.equals(id)?prefix(low,min,max,cap):(long)low*(low+1)/2;return make(id,min+low,min+(int)(index-start));}
 static Question next(String id,Random random,CurriculumLimits limits,Map<String,Integer> recent){int min=limits.givenMinimum(1000),max=limits.givenMaximum(limits.hasWholeMaximum()?1000000:999999),cap=limits.resultMaximum(2*max);return LongIndexedQuestionSupply.choose(boundedCount(id,min,max,cap),i->bounded(id,min,max,cap,i),random,limits,recent);}
 public static void attach(Question q){int[] v=read(q);if(v!=null)q.studyGuide=guide(v[0],v[1],ADD.equals(q.skillId),"large-mental-decomposition-v1");}
 static StudyGuide guide(int a,int b,boolean add,String version){StudyGuide g=new StudyGuide().transfer(false);g.teachingVersion=version;g.step("첫 수를 쓰세요.","시작 수 = ","",""+a);int running=a;for(int column=6,power=1000000;column>=0;column--,power/=10){int digit=b/power%10;if(digit==0&&!(b==0&&column==0))continue;int part=digit*power;g.step("둘째 수의 "+PLACES[column]+" 자리값을 쓰세요.","자리값 = ","",""+part);running+=add?part:-part;g.step(add?"현재 수에 이 자리값을 더하세요.":"현재 수에서 이 자리값을 빼세요.",add?"현재 수 + 자리값 = ":"현재 수 − 자리값 = ","",""+running);}return g;}
 static Checker.Result check(Question q,List<String> answers){int[] v=read(q);if(v==null||answers==null||answers.size()!=1||answers.get(0)==null||!answers.get(0).trim().matches("[0-9]{1,7}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");return Integer.parseInt(answers.get(0).trim())==v[2]?new Checker.Result(Checker.Status.CORRECT,-1,"정답"):new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");}
}
